--- a/src/visits.rs
+++ b/src/visits.rs
@@ -1,16 +1,38 @@
 use crate::audit::Audit;
 use crate::metrics::Metrics;
 use crate::repo::Repo;

 pub struct Visits {
     repo: Repo,
     audit: Audit,
     metrics: Metrics,
 }

 impl Visits {
+    /// Сохраняет приём и оставляет след в журнале действий.
+    pub fn record(&self, visit: &Visit) -> u64 {
+        let id = self.repo.save(visit).ok().unwrap_or_default();
+
+        self.audit.push(&visit.pet_id, id);
+        self.metrics.inc("visits.recorded");
+
+        id
+    }
 }
